def base(title,desc,page,body):
    head = f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f7f6f0"><meta name="description" content="{escape(desc)}"><meta name="color-scheme" content="light"><link rel="manifest" href="manifest.webmanifest"><link rel="icon" href="assets/img/brand-mark.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="assets/img/brand-mark.svg"><link rel="stylesheet" href="assets/css/site.css"><title>{escape(title)} | SmartResto</title></head><body data-page="{page}">'''
    register = '''<script src="assets/js/site.js" defer></script><script>if('serviceWorker' in navigator && location.protocol !== 'file:') window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js').catch(()=>{}));</script></body></html>'''
    return head + header(page) + '<main>' + body + '</main>' + footer() + register

