def business_card(name,kind,rating,img,price,cat):
    return f'''<article class="card card-lift" data-card data-category="{cat}" data-search="{escape(name+' '+kind)}"><img class="card-image" src="{img}" alt="{escape(name)}"><div class="card-body"><div class="price-row"><span class="tag">{escape(kind)}</span><button class="heart" aria-label="Guardar favorito">♡</button></div><h3 class="card-title">{escape(name)}</h3><div class="meta">{escape(rating)} · Información demostrativa</div><div class="card-foot"><span class="price">{escape(price)}</span><a class="text-link" href="descubrir.html">Ver negocio ↗</a></div></div></article>'''

