pages['nosotros.html']=base('Sobre SmartResto','Conoce la visión de SmartResto.','', '''<section class="page-hero"><div class="container"><span class="eyebrow">Nuestra visión</span><h1 class="display">Conectar el mundo gastronómico, <em>un sabor a la vez.</em></h1><p class="lead">SmartResto busca conectar a comensales, negocios y experiencias en un mismo ecosistema digital.</p></div></section><section class="section"><div class="container split"><div><h2 class="display" style="font-size:3rem">Descubrir. Gestionar. <em>Disfrutar.</em></h2><p class="lead">La propuesta reúne marketplace, recomendación inteligente, gestión empresarial, comercio gastronómico, cartas QR, fidelización, cocina en casa y experiencias 3D.</p></div><div class="feature-visual"><img src="https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1000&q=85" alt="Experiencia gastronómica compartida"></div></div></section>''')
pages['como-funciona.html']=base('Cómo funciona','Conoce el recorrido conectado de SmartResto.','', '''<section class="page-hero"><div class="container"><span class="eyebrow">Cómo funciona</span><h1 class="display">Un ecosistema. <em>Todo conectado.</em></h1><p class="lead">Desde el descubrimiento hasta la valoración posterior al consumo.</p></div></section><section class="section"><div class="container step-grid"><div class="step"><div class="step-no">01</div><h3>Descubre</h3><p>Busca negocios, platos, categorías y promociones.</p></div><div class="step"><div class="step-no">02</div><h3>Elige</h3><p>Salir a comer, delivery o cocinar en casa.</p></div><div class="step"><div class="step-no">03</div><h3>Consume</h3><p>Reserva, escanea QR, pide y realiza seguimiento.</p></div><div class="step"><div class="step-no">04</div><h3>Conecta</h3><p>Registra consumos confirmados, puntos y reseñas.</p></div></div></section>''')
pages['ayuda.html']=base('Centro de ayuda','Resuelve dudas sobre SmartResto.','', '''<section class="page-hero"><div class="container"><span class="eyebrow">Estamos para ayudarte</span><h1 class="display">Centro de <em>ayuda.</em></h1><p class="lead">Encuentra respuestas sobre cuentas, pedidos, cartas QR, negocios y privacidad.</p></div></section><section class="section"><div class="container" style="max-width:850px"><div class="faq-item"><button class="faq-q">¿Necesito una cuenta para explorar? <span>＋</span></button><div class="faq-a">La navegación pública y consulta de información disponible podrán realizarse sin cuenta. Para guardar preferencias, pedidos o puntos necesitarás iniciar sesión.</div></div><div class="faq-item"><button class="faq-q">¿Cómo funciona una carta QR? <span>＋</span></button><div class="faq-a">Cada QR puede identificar negocio, sucursal, piso, zona y mesa. El cliente consulta la carta y, según la configuración del local, puede enviar pedidos o solicitar atención.</div></div><div class="faq-item"><button class="faq-q">¿La IA publica automáticamente los platos? <span>＋</span></button><div class="faq-a">La IA prepara borradores. El empresario debe confirmar precios, ingredientes, alérgenos, cantidades y disponibilidad antes de publicar.</div></div><div class="faq-item"><button class="faq-q">¿Cómo se registran las visitas y puntos? <span>＋</span></button><div class="faq-a">Los puntos se vincularán a compras y visitas verificadas, con controles para evitar duplicados y reversión ante cancelaciones.</div></div><div class="faq-item"><button class="faq-q">¿SmartResto funciona offline? <span>＋</span></button><div class="faq-a">Como PWA podrá abrir recursos previamente almacenados y conservar ciertos borradores. Pedidos, pagos y validaciones necesitan conexión con el servidor.</div></div></div></section>''')
pages['contacto.html']=base('Contacto','Contacta con el equipo SmartResto.','', '''<section class="page-hero"><div class="container"><span class="eyebrow">Hablemos</span><h1 class="display">Construyamos algo <em>con buen sabor.</em></h1><p class="lead">Escríbenos para consultas, alianzas, incorporación de negocios o información comercial.</p></div></section><section class="section"><div class="container grid grid-2"><div><h2 class="serif" style="font-size:2.3rem">¿En qué podemos ayudarte?</h2><p class="lead">Este formulario es demostrativo. Los canales oficiales se configurarán antes del lanzamiento público.</p><div class="soft-panel" style="padding:22px;margin-top:20px"><strong>Alianzas y negocios</strong><p class="muted">Cuéntanos sobre tu negocio gastronómico o integración.</p><a class="text-link" href="negocios.html">Ver planes empresariales ↗</a></div></div><form class="card form-shell" data-demo-form="contact" style="margin:0;width:100%"><div class="form-field"><label>Nombre</label><input required placeholder="Tu nombre"></div><div class="form-field"><label>Correo</label><input type="email" required placeholder="tu@correo.com"></div><div class="form-field"><label>Motivo</label><select required><option value="">Seleccionar</option><option>Consulta general</option><option>Registrar un negocio</option><option>Alianzas</option><option>Soporte</option></select></div><div class="form-field"><label>Mensaje</label><textarea rows="4" required placeholder="Cuéntanos más..."></textarea></div><button class="btn btn-primary btn-block">Enviar mensaje ↗</button></form></div></section>''')

legal_sections={
 'terminos.html':('Términos y condiciones','Reglas generales de uso de SmartResto.','Uso del servicio','Este documento es un borrador informativo para el prototipo. Antes de prestar el servicio deberán definirse las condiciones contractuales, responsabilidades de cada negocio, reglas de pedidos, pagos, cancelaciones, reembolsos, puntos y contenido publicado. SmartResto conecta usuarios y negocios; las condiciones finales deberán describir con claridad qué servicios presta la plataforma y cuáles corresponden a cada establecimiento.'),
 'privacidad.html':('Política de privacidad','Información sobre el tratamiento de datos personales.','Privacidad y datos personales','Este contenido es una estructura preliminar y requiere revisión legal antes de producción. La versión final deberá identificar al responsable del tratamiento, finalidades, bases legales, datos recopilados, destinatarios, plazos de conservación, medidas de seguridad y mecanismos para ejercer derechos. La ubicación, historial de consumo y preferencias deberán tratarse con transparencia y controles adecuados.'),
 'cookies.html':('Política de cookies','Conoce y administra las tecnologías de almacenamiento.','Cookies y preferencias','SmartResto distinguirá almacenamiento esencial, analítica y personalización. El consentimiento de cookies no equivale a autorización para geolocalización ni para notificaciones push. El usuario podrá revisar y modificar sus preferencias. La implementación final deberá documentar proveedores, duración, finalidades y opciones de rechazo.'),
 'accesibilidad.html':('Accesibilidad','Compromiso con una experiencia inclusiva.','Diseño accesible','El prototipo contempla navegación adaptable, contraste, foco visible, etiquetas de formularios y respeto por la preferencia de movimiento reducido. Antes del lanzamiento deben realizarse pruebas con lector de pantalla, teclado, zoom, contraste y dispositivos reales. Las imágenes deberán tener textos alternativos útiles.'),
 'comunidad.html':('Comunidad','Descubre historias y novedades gastronómicas.','Una comunidad de sabores','SmartResto podrá reunir experiencias, reseñas verificadas, recomendaciones y contenido de negocios. Las publicaciones deberán contar con herramientas de denuncia, moderación y control de contenido. Los rankings deberán basarse en señales verificables y no solamente en impresiones o publicidad.')
}
for fn,(title,desc,h,txt) in legal_sections.items():
    pages[fn]=base(title,desc,'',f'''<section class="page-hero"><div class="container"><span class="eyebrow">SmartResto · Información</span><h1 class="display">{title.split()[0]} <em>{' '.join(title.split()[1:])}</em></h1><p class="lead">{desc}</p></div></section><section class="section"><div class="container" style="max-width:850px"><article class="card pad"><span class="tag">Documento preliminar</span><h2 class="serif" style="font-size:2rem">{h}</h2><p class="lead">{txt}</p><p class="form-note">El texto mostrado es referencial y no reemplaza la documentación legal, contractual o de cumplimiento que deberá aprobarse para el servicio real.</p></article></div></section>''')

for name,html in pages.items(): (ROOT/name).write_text(html,encoding='utf-8')

